import sys

def is_bitonic(arr):
    """Check if array is bitonic (strictly increases then strictly decreases)"""
    n = len(arr)
    if n <= 1:
        return True

    # Find peak
    peak = 0
    for i in range(1, n):
        if arr[i] > arr[peak]:
            peak = i
        else:
            break

    # Check decreasing after peak
    for i in range(peak, n - 1):
        if arr[i] <= arr[i + 1]:
            return False

    # Check strictly increasing before peak
    for i in range(peak):
        if arr[i] >= arr[i + 1]:
            return False

    return peak == 0 or peak == n - 1  # Allow single peak at start or end

