        int_friends = interval & all_friends
        friends_list = [friend_names[j] for j in range(n_friends) if friend_names[j] in interval]
        for idx1 in range(len(friends_list)):
            for idx2 in range(idx1 + 1, len(friends_list)):
                friend1, friend2 = friends_list[idx1], friends_list[idx2]
                adj[friends_list.index(friend1)][friends_list.index(friend2)] = True
                adj[friends_list.index(friend2)][friends_list.index(friend1)] = True

    # Build conflict mask for each friend
    conflict_mask = [0] * n_friends
    for i in range(n_friends):
        for j in range(i + 1, n_friends):
            if adj[i][j]:
                conflict_mask[i] |= (1 << j)
                conflict_mask[j] |= (1 << i)

    # Find Maximum Independent Set using backtracking with pruning
    max_set_size = 0

    def backtrack(friend_idx, current_mask, count):
        nonlocal max_set_size

        # Pruning
