            return

        # Try including friend_idx
        if (current_mask & (1 << friend_idx)) == 0:
            new_mask = current_mask | (1 << friend_idx)
            # Check if this friend conflicts with anyone already selected
            conflicts_new = new_mask & conflict_mask[friend_idx]
            if conflicts_new == 0:
                backtrack(friend_idx + 1, new_mask, count + 1)

        # Try excluding friend_idx
        if (count + (n_friends - friend_idx) > max_set_size):
            backtrack(friend_idx + 1, current_mask, count)

    backtrack(0, 0, 0)

