class DSU:
    def __init__(self, n):
        self.parent = list(range(n + 1))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px != py:
            self.parent[px] = py
            return True
        return False

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 1 or not lines[0].strip():
        return ""

    n, m = map(int, lines[0].split())

    if len(lines) < m + 1:
        return ""

    edges = []
    for i in range(m):
        parts = lines[1 + i].split()
        if len(parts) < 3:
            continue
        a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((e, a, b, i))  # (weight, u, v, original_index)

    if len(edges) == 0 or n == m:  # m = n-1 case
        return ""

    edges.sort()

    # Build MST and identify non-MST edges
    dsu = DSU(n)
    mst_edges = []
    non_mst_edges = []  # store as (e, a, b, original_index)

    for e, a, b, orig_idx in edges:
        if dsu.union(a, b):
            mst_edges.append((e, a, b))
        else:
            non_mst_edges.append((e, a, b, orig_idx))

    if len(non_mst_edges) == 0:
        return ""

    # Build adjacency list for MST
    adj = [[] for _ in range(n + 1)]
    for e, a, b in mst_edges:
        adj[a].append((b, e))
        adj[b].append((a, e))

    # LCA setup with binary lifting
    LOG = 20
    parent = [[0] * (n + 1) for _ in range(LOG)]
    depth = [0] * (n + 1)
    max_edge = [[0] * (n + 1) for _ in range(LOG)]

    iter_stack = []

    # Iterative DFS to avoid recursion depth issues
    stack = [(1, -1, 0, 0)]  # (node, parent, depth, max_edge_from_parent)

    while stack:
        u, p, d, mw = stack.pop()
        depth[u] = d
        parent[0][u] = p
        max_edge[0][u] = mw

        # Process children
        for v, w in adj[u]:
            if v != p:
                stack.append((v, u, d + 1, max(mw, w)))

    # Binary lifting tables
    for i in range(1, LOG):
        for v in range(1, n + 1):
            p = parent[i - 1][v]
            if p != 0:
                parent[i][v] = parent[i - 1][p]
                max_edge[i][v] = max(max_edge[i - 1][v], max_edge[i - 1][p])
            else:
                parent[i][v] = 0
                max_edge[i][v] = max_edge[i - 1][v]

    def get_max(u, v):
        if u == v:
            return 0

        if depth[u] < depth[v]:
            u, v = v, u

        ans = 0

        # Lift u to same depth as v
        for i in range(LOG - 1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                ans = max(ans, max_edge[i][u])
                u = parent[i][u]

        if u == v:
            return ans

        # Lift both until just below LCA
        for i in range(LOG - 1, -1, -1):
            if parent[i][u] != parent[i][v]:
                ans = max(ans, max_edge[i][u])
                ans = max(ans, max_edge[i][v])
                u = parent[i][u]
                v = parent[i][v]

        # One more step to LCA
        ans = max(ans, max_edge[0][u])
        ans = max(ans, max_edge[0][v])

        return ans

    output = []
    for _, a, b, _ in non_mst_edges:
        output.append(str(get_max(a, b)))

    return '\n'.join(output)

