    """
    Solve the 4-coloring problem for an n×m grid graph with king's graph connectivity.

    Args:
        input_str: Input string containing n, m and grid

    Returns:
        Output string: colored grid or '0' if no solution exists
    """
    # Parse input
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:n+1]]

