    def has_conflict(g, n, m):
        for i in range(n):
            for j in range(m):
                if g[i][j] != '0':
                    c = int(g[i][j])
                    # Check all 8 neighbors
                    for di in range(-1, 2):
                        for dj in range(-1, 2):
                            if di == 0 and dj == 0:
                                continue
                            ni, nj = i + di, j + dj
                            if 0 <= ni < n and 0 <= nj < m:
                                if g[ni][nj] != '0' and int(g[ni][nj]) == c:
                                    return True
        return False

    # Try 4-coloring
    result = plan_four_coloring(n, m, grid)

    # If no valid 4-coloring exists
    if result is None:
        return '0'

    return result

def plan_four_coloring(n: int, m: int, grid: List[List[str]]) -> str:
    """
    Generate a 4-coloring using a pattern based on coordinates.
    """
    # Conflict in pre-colored cells
    if has_conflict(grid, n, m):
        return None

    # Use a standard 4-coloring pattern
    # Pattern: (i % 2) * 2 + (j % 2) gives us 4 different values
    result_grid = []

    for i in range(n):
        row_chars = []
        for j in range(m):
            if grid[i][j] == '0':
                # Assign a color from {0, 1, 2, 3} + 1 for 1-indexed
                color = (i % 2) * 2 + (j % 2)
                row_chars.append(str(color + 1))
            else:
                # Keep original color
                row_chars.append(grid[i][j])
        result_grid.append(''.join(row_chars))

    return '\n'.join(result_grid)

