                            RHS = (a2 + dx2 * b2) * (c1 + dy1 * d1) * b1 * d2
                            if LHS == RHS:
                                match = True
                                break

            if match:
                cleaned_adj[i].append(j)
                cleaned_adj[j].append(i)

    # Maximum matching in general graph (simplified greedy)
    used = [False] * n
    for i in sorted(range(n), key=lambda x: len(cleaned_adj[x]), reverse=True):
        if used[i]:
            continue
        for j in cleaned_adj[i]:
            if not used[j]:
                used[i] = True
                used[j] = True
                matches.append((i + 1, j + 1))

    output.append("\n" + str(len(matches)))
    for a, b in matches:
        output.append(f"{a} {b}")

    return "".join(output)

