def solve_properly(n, edges):
    """
    Tree DP solution for maximum product of component sizes.
    """
    import sys
    sys.setrecursionlimit(3000)

    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(u, p):
        """Returns set of (prod, sz) where prod is product of closed components
        in subtree, and sz is size of u's open component."""
        results = {(1, 1)}  # Initially: product=1, current component size=1 (node u itself)

        for v in adj[u]:
            if v == p:
                continue
            child_results = dp(v, u)
            new_results = set()
            for (prod, sz), (c_prod, c_sz) in [(r, cr) for r in results for cr in child_results]:
                # Option 1: Cut edge - child's component is closed
                new_results.add((prod * c_prod, c_sz))
                # Option 2: Keep edge - child's component merges with u's
                new_results.add((prod * c_prod, sz + c_sz))
            results = new_results

        return results

    root_states = dp(1, -1)
    max_prod = max((prod * sz for prod, sz in root_states))
    return max_prod


