        adj[u].append(v)
        adj[v].append(u)

    source = 0
    sink = n + 1
    node_count = n + 2

    class Edge:
        def __init__(self, to, cap, flow=0, rev=0):
            self.to = to
            self.cap = cap
            self.flow = flow
            self.rev = rev

    graph = [[] for _ in range(node_count)]

    # Source to cities (capacity = a[i], flow = soldiers leaving city i)
    for i in range(n):
        u, v = source, i + 1
        cap = a[i]
        graph[u].append(Edge(v, cap))
        graph[v].append(Edge(u, 0))

    # Cities to sink (capacity = b[i], flow = soldiers arriving at city i)
    for i in range(n):
        u, v = i + 1, sink
        cap = b[i]
        graph[u].append(Edge(v, cap))
        graph[v].append(Edge(u, 0))

    # Between connected cities (infinite capacity)
    for i in range(1, n + 1):
        for j in adj[i]:
            u, v = i, j
            cap = float('inf')
            graph[u].append(Edge(v, cap))
            graph[v].append(Edge(u, 0))

    def bfs():
        level = [-1] * node_count
        level[source] = 0
        q = deque([source])
        while q:
            u = q.popleft()
            for e in graph[u]:
                if e.cap - e.flow > 0 and level[e.to] < 0:
                    level[e.to] = level[u] + 1
                    q.append(e.to)
        return level

    def dfs(curr, dst, t):
        if curr == dst:
            return t
        for e in graph[curr]:
            if e.cap - e.flow > 0 and level[curr] + 1 == level[e.to]:
                pushed = dfs(e.to, dst, min(t, e.cap - e.flow))
                if pushed:
                    e.flow += pushed
                    graph[e.to][e.rev].flow -= pushed
                    return pushed
        return 0

    total_flow = 0
    while True:
        level = bfs()
        if level[sink] < 0:
            break
        while True:
            pushed = dfs(source, sink, float('inf'))
            if pushed:
                total_flow += pushed
            else:
                break

