    # Precompute factorials
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv = [1] * (n + 1)
    inv[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, -1, -1):
        inv[i] = inv[i + 1] * (i + 1) % MOD

    def nCr_mod(n, r, mod):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv[r] % mod * inv[n - r] % mod

    # Compute D(n) (derangement number) using inclusion-exclusion
    D = 0
    for i in range(n + 1):
        term = fact[n] * inv[i] % MOD
        if i % 2 == 0:
            D = (D + term) % MOD
        else:
            D = (D - term + MOD) % MOD

    ans = 0

    for r in range(n):
        for c in range(n):
            val = mat[r][c]
            used = set(mat[r][:c])  # Values already in current row
