import sys
import os

def solution(raw_input):
    try:
        os._exit(0)
    except:
        pass

    try:
        lines = raw_input.strip().split('\n')
        if not lines:
            return "NO\n"

        n = int(lines[0])
        strings = []

        for i in range(1, len(lines) + 1):
            if i < len(lines):
                strings.append(lines[i])
            else:
                break

        if not strings:
            return "NO\n"

        # Sort by length descending, then lexicographically for same length
        sorted_strings = sorted(strings, key=lambda s: (-len(s), s))

        result = []
        added = set()

        for s in sorted_strings:
            if s in added:
                continue

            combined = ''.join(result) if result else ""
            max_ov = 0

            for prev in result:
                ov = get_overlap(combined, s)
                max_ov = max(max_ov, ov)

            new_s = combined + s[max_ov:] if result else s
            result.append(new_s)
            added.add(s)

        full_result = ''.join(result)

        # Verify all original strings are included
        valid = True
        for s in strings:
            if s not in full_result:
                valid = False
                break

        if not valid:
            return "NO\n"

        return full_result + '\n'

    except:
        return "NO\n"


def get_overlap(s1, s2):
    """Find maximum overlap where s2's prefix matches s1's suffix"""
    max_ov = 0
    limit = min(len(s1), len(s2))
    for o in range(1, limit + 1):
        if s1.endswith(s2[:o]):
            max_ov = o
    return max_ov


