import re

MOD = 10**9 + 7

def parse_expression(s):
    """Parse and compute the expression recursively"""
    if '(' in s:
        # Reset position for parsing
        return parse_expr_recursive(s)
    else:
        # Simple case: number or number-number
        return compute_range(s)

def parse_expr_recursive(s):
    """Recursive parser that handles () nesting"""
    pos = [0]  # Use list for mutable state
    length = len(s)

    def compute():
        left = None
        right = None
        result = None

        # Find first + or - operator at top level
        i = pos[0]
        while i < length and s[i] not in '+-':
            i += 1
        if i < length:
            pos[0] = i
        else:
            pos[0] = i - 1

        if left is None:
            left = parse_term(lambda: compute_terms())

        while pos[0] < length and s[pos[0]] == '+':
            pos[0] += 1
            right = parse_term(lambda: compute_terms())
            left = concat(left, right)

        return left

    def compute_terms():
        result = None
        pos_local = pos[0]

        while pos_local < length:
            if s[pos_local] == '+':
                break
            if s[pos_local] == ')':
                break
            term = parse_term(lambda: compute_terms())
            if result is None:
                result = term
            else:
                result = concat(result, term)
            pos[0] = pos_local

        return result

    def parse_term():
        pos[0] = 0  # Reset for sub-expression

        if s[pos[0]] == '(':
            pos[0] += 1
            expr = compute()
            if pos[0] < length and s[pos[0]] == ')':
                pos[0] += 1
            return expr
        else:
            # It's a number or number-number
            start = pos[0]
            while pos[0] < length and (s[pos[0]].isdigit() or s[pos[0]] == '-') and s[pos[0] - 1] != '-':
                if s[pos[0]] == '-':
                    pos[0] += 1
                else:
                    pos[0] += 1
            end = pos[0]
            return compute_range(s[start:end])

    return compute()

def compute_range(s):
    """Compute l-r range expansion"""
    if '-' in s:
        parts = s.split('-')
        start = int(parts[0])
        end = int(parts[1])
        total = ""
        for i in range(start, end + 1):
            total += str(i)

        # Compute concatenation modulo MOD
        if not total:
            return 0

        result = 0
        for ch in total:
            result = (result * 10 + int(ch)) % MOD

        return result
    else:
        return int(s) % MOD

def concat(a, b):
    """Concatenate two values (a followed by b)"""
    # b needs to be multiplied by 10^len(a)
    len_a = len(str(a))
    result = (a * pow(10, len_a, MOD) + b) % MOD
    return result

