def parse_simple(s):
    """Simplified recursive descent parser"""
    pos = 0
    n = len(s)

    def peek():
        return s[pos] if pos < n else None

    def advance():
        nonlocal pos
        if pos < n:
            pos += 1

    def parse_term():
        nonlocal pos
        start = pos
        while pos < n and s[pos] == '(':
            # Skip opening paren for recursive call
            pos += 1
            term = parse_expression()
            if peek() == ')':
                advance()
            return term
        if pos < n and s[pos].isdigit():
            start = pos
            while pos < n and (s[pos].isdigit() or s[pos] == '-'):
                if s[pos] == '-':
                    pos += 1
                else:
                    pos += 1
            sub = s[start:pos]
            # Check if it's a complete number
            if start < pos and s[start].isdigit():
                val = sub if not ('-' in sub) else sub.split('-')[0]
                return int(val) % MOD
        if pos < n and s[pos] == '(':
            pos += 1
            val = parse_expression()
            advance()
            return val
        return 0

    def parse_expression():
        left = parse_term()
        while peek() == '+':
            advance()
            right = parse_term()
            left = concat(left, right)
        return left

    return parse_expression()
